//! Inline lucide icons (`icon_data.rs`, generated by `scripts/gen-icons.mjs`). Colour follows
//! `currentColor`, so a parent's CSS `color` tints it.

use leptos::prelude::*;

use super::icon_data::Ico;

#[component]
pub fn Icon(
    #[prop(into)] ico: Signal<Ico>,
    #[prop(default = 18.0)] size: f64,
    #[prop(default = 1.6)] stroke: f64,
    #[prop(optional, into)] class: String,
) -> impl IntoView {
    view! {
        <svg
            class=format!("ico {class}")
            width=size
            height=size
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width=stroke
            stroke-linecap="round"
            stroke-linejoin="round"
            aria-hidden="true"
            inner_html=move || ico.get().body()
        ></svg>
    }
}
